using System;
using System.IO;
using BiliLite.Helpers;
using BiliLite.Modules;
using BiliLite.Parsing;
using BiliLite.Parsing.Video;
using Newtonsoft.Json;

namespace C1Probe
{
    /// <summary>
    /// C1: the video detail pipeline keeps ugc_season and the detail page renders it.
    ///
    /// Executed against product source: Models/VideoCollections.cs and the VideoDetailModel
    /// slice of Modules/Detail/VideoDetailVM.cs (build/DetailModels.cs is generated by run.sh
    /// from the real file, from "public class VideoDetailModel" to the end of that file).
    /// Pages/VideoDetailPage.xaml(.cs) cannot run outside UWP, so their wiring is asserted by
    /// reading the source; every such check is named "source:" below.
    /// </summary>
    public static class Program
    {
        private static int _passed;

        public static int Main()
        {
            CollectionIsRetained();
            EpisodeCoverAndAuthorFallBackToArc();
            EpisodeLevelValuesWinOverArc();
            MissingArcFallsBackWithoutThrowing();
            DetailWithoutCollectionHasNoCollection();
            SingleSectionAndEpisode();
            EmptySectionsHideTheCollection();
            NullRelatesDoesNotThrow();
            WebViewParsesIntoTheWireShape();
            WebViewShapeMistakesArePayloadFailures();
            MapperSynthesisesShortLinkAndDefaults();
            AppViewKeepsOwnerExtAndIgnoresWireReqUser();
            RelatesFailureKeepsThePage();
            RejectedAndNonJsonBodiesAreSilent();
            TagsRelationAndStatesParseTheirScalars();
            ActionsReportWhatTheServerSaid();
            FavoriteCreatedListParsesWithoutReindexingJson();
            ParsersDoNotReachTheUi();
            ViewModelWiringDecidesOnParseResults();
            PageReadsTheCollectionFromTheDetailResponse();
            PageShowsTheCollection();

            Console.WriteLine("PASS " + _passed + " assertions");
            return 0;
        }

        private static void CollectionIsRetained()
        {
            var detail = ParseDetail(CollectionDetailJson);

            Check(detail.UgcSeason != null, "ugc_season is retained on VideoDetailModel");
            Check(detail.UgcSeason.Id == 514597, "collection id is kept");
            Check(detail.UgcSeason.Title == "DIY 的 VLOG", "collection title is kept");
            Check(detail.UgcSeason.Cover == CollectionCover, "collection cover is kept");
            Check(detail.UgcSeason.Intro == "记录日常", "collection intro is kept");
            Check(detail.UgcSeason.Stat != null && detail.UgcSeason.Stat.View == 64938, "collection view count is kept");
            Check(detail.UgcSeason.Stat.Favorite == 315, "collection favourite count is kept from stat.fav");
            Check(detail.UgcSeason.Stat.SeasonId == 514597, "collection stat carries season_id");
            Check(detail.showUgcSeason, "showUgcSeason is true when sections exist");

            Check(detail.UgcSeason.Sections != null && detail.UgcSeason.Sections.Count == 2, "both sections are kept");
            Check(detail.UgcSeason.Sections[0].Id == 595012, "section id is kept");
            Check(detail.UgcSeason.Sections[0].Title == "正片", "section title is kept");
            Check(detail.UgcSeason.Sections[0].Episodes.Count == 3, "first section keeps its episodes");

            var episode = detail.UgcSeason.Sections[0].Episodes[0];
            Check(episode.Aid == "555272312", "episode aid is kept as the canonical numeric id");
            Check(episode.Bvid == "BV1iv4y1M7iu", "episode bvid is kept");
            Check(episode.Cid == "756877509", "episode cid is kept");
            Check(episode.Title == "英国旅游VLOG | 发小带你逛哈利波特制片厂", "episode title is kept");
            Check(episode.Page != null && episode.Page.Duration == 1126, "episode duration comes from page.duration");
            Check(detail.UgcSeason.Sections[1].Title == "花絮"
                && detail.UgcSeason.Sections[1].Episodes[0].Aid == "555272313",
                "the second section keeps its own episodes");
        }

        private static void EpisodeCoverAndAuthorFallBackToArc()
        {
            var episode = ParseDetail(CollectionDetailJson).UgcSeason.Sections[0].Episodes[0];

            Check(episode.Cover == "http://i0.hdslb.com/bfs/archive/cover-a.jpg",
                "episode without cover falls back to arc.pic");
            Check(episode.Author != null && episode.Author.Name == "DIYgod",
                "episode without author falls back to arc.author");
        }

        private static void EpisodeLevelValuesWinOverArc()
        {
            var episode = ParseDetail(CollectionDetailJson).UgcSeason.Sections[0].Episodes[1];

            Check(episode.Cover == "http://i0.hdslb.com/bfs/archive/cover-b.jpg",
                "episode level cover wins over arc.pic");
            Check(episode.Author != null && episode.Author.Name == "客串UP",
                "episode level author wins over arc.author");
            Check(episode.Page != null && episode.Page.Duration == 982, "each episode keeps its own page.duration");
        }

        private static void MissingArcFallsBackWithoutThrowing()
        {
            var episode = ParseDetail(CollectionDetailJson).UgcSeason.Sections[0].Episodes[2];

            Check(episode.Arc == null, "episode without arc keeps arc null");
            Check(episode.Cover == "http://i0.hdslb.com/bfs/archive/cover-c.jpg",
                "episode without arc uses its own cover");
            Check(episode.Author == null, "episode without arc and author has no author");
        }

        private static void DetailWithoutCollectionHasNoCollection()
        {
            var detail = ParseDetail(NoCollectionDetailJson);

            Check(detail.UgcSeason == null, "a detail response without ugc_season leaves the collection null");
            Check(!detail.showUgcSeason, "showUgcSeason is false when the response has no collection");
        }

        private static void SingleSectionAndEpisode()
        {
            var detail = ParseDetail(SingleEpisodeDetailJson);

            Check(detail.UgcSeason != null && detail.UgcSeason.Sections.Count == 1, "a single section collection is kept");
            Check(detail.UgcSeason.Sections[0].Episodes.Count == 1, "a single episode section is kept");
            Check(detail.UgcSeason.Sections[0].Episodes[0].Aid == detail.aid,
                "the single episode carries the current video aid used for selection");
        }

        private static void EmptySectionsHideTheCollection()
        {
            var detail = ParseDetail(EmptySectionsDetailJson);

            Check(detail.UgcSeason != null && detail.showUgcSeason == false,
                "a collection without episodes is not shown");
        }

        private static void PageReadsTheCollectionFromTheDetailResponse()
        {
            var vm = ReadSource("src/BiliLite.UWP/Modules/Detail/VideoDetailVM.cs");

            Check(vm.Contains("[JsonProperty(\"ugc_season\")]"), "source: the detail model maps ugc_season");
            Check(vm.Contains("public VideoUgcSeason UgcSeason { get; set; }"), "source: the detail model exposes UgcSeason");
            Check(vm.Contains("var webResult = await videoAPI.DetailWebInterface(id, isbvid).Request();"),
                "source: the collection still arrives through the existing web detail request");
            Check(!ReadSource("src/BiliLite.UWP/Api/VideoAPI.cs").Contains("ugc_season"),
                "source: no separate collection endpoint is requested");
            Check(ReadSource("src/BiliLite.UWP/BiliLite.UWP.csproj").Contains("Models\\VideoCollections.cs"),
                "source: the new model file is compiled by the UWP project");
        }

        private static void PageShowsTheCollection()
        {
            var page = ReadSource("src/BiliLite.UWP/Pages/VideoDetailPage.xaml.cs");
            var xaml = ReadSource("src/BiliLite.UWP/Pages/VideoDetailPage.xaml");

            Check(page.Contains("ApplyUgcSeason();") && page.Contains("private void ApplyUgcSeason()"),
                "source: the detail page applies the collection after each detail load");
            Check(page.Contains("if (info == null || !info.showUgcSeason)") && page.Contains("RemoveUgcSeason();"),
                "source: a response without a collection removes the collection tab");
            Check(page.Contains("ugcSeasonAid = info.aid;"),
                "source: the selected entry is keyed by the canonical aid from VideoInfo");
            Check(page.Contains("FirstOrDefault(x => x.Aid == ugcSeasonAid"), "source: the entry matching that aid is selected");
            Check(page.Contains("if (!pivot.Items.Contains(ugcSeasonPivotItem))"),
                "source: refreshes reuse the existing collection tab instead of adding another");
            Check(page.Contains("await InitializeVideo(item.Aid, PlayTargetStart.Resume);"),
                "source: clicking an episode plays it through InitializeVideo with the user's resume");
            Check(page.Contains("if (item == null || item.Aid == ugcSeasonAid) return;"),
                "source: programmatic selection of the current video does not reload it");
            Check(page.Contains("new TextBlock() { Text = \"合集\", FontSize = 18 }"), "source: the collection is its own pivot tab");
            Check(page.Contains("Text = info.UgcSeason.Title") && page.Contains("Text = info.UgcSeason.Intro"),
                "source: the tab shows the collection title and intro");
            Check(page.Contains("Text = section.Title"), "source: each section renders its title header");
            Check(page.Contains("Duration = FormatDuration(episode.Page?.Duration ?? 0)"),
                "source: the row duration is formatted from page.duration");
            Check(page.Contains("var listView = playlistPivotItem?.Content as ListView;"),
                "source: playlist auto-next no longer depends on the pivot item order");

            Check(xaml.Contains("x:Key=\"UgcSeasonEpisodeTpl\""), "source: the episode row template exists");
            var template = xaml.Substring(xaml.IndexOf("x:Key=\"UgcSeasonEpisodeTpl\"", StringComparison.Ordinal));
            template = template.Substring(0, template.IndexOf("</DataTemplate>", StringComparison.Ordinal));
            Check(template.Contains("{Binding Cover, Converter={StaticResource imageConvert2}") && template.Contains("{Binding Title}")
                && template.Contains("{Binding Author}") && template.Contains("{Binding Duration}"),
                "source: the row shows a converted cover, title, author and duration like the playlist template");
        }

        /// <summary>
        /// The trap this migration had to fix: VideoDetailModel.relates used to dereference value
        /// without a null check, so a wire "relates": null threw inside deserialization and the old
        /// VM folded that into a null page. Run against the pre-change source this method fails on
        /// its first check.
        /// </summary>
        private static void NullRelatesDoesNotThrow()
        {
            VideoDetailModel detail = null;
            try
            {
                detail = JsonConvert.DeserializeObject<VideoDetailModel>(RelatesNullDetailJson);
            }
            catch (Exception ex)
            {
                Check(false, "a wire relates: null no longer throws inside deserialization (" + ex.GetType().Name + ")");
            }

            Check(detail != null, "a wire relates: null still decodes the detail model");
            Check(detail.relates == null, "a wire relates: null leaves no related list instead of throwing");
            Check(detail.bvid == "BV1GJ411x7h7" && detail.title == "只有一条推荐为 null 的详情",
                "the rest of the model survives relates: null");

            //同一条响应走解析+映射:视图里的 relates 不属于这个端点,由相关视频那条读合并
            var parsed = WebVideoViewParser.ParseWebVideoView(Ok(RelatesNullEnvelopeJson));
            Check(parsed.IsSuccess, "a view body that carries relates: null still parses");
            var page = WebVideoViewMapper.MapWebVideoView(parsed.Value);
            Check(page != null, "a view body that carries relates: null still maps to a page");
            page.relates = WebVideoViewMapper.MapWebVideoRelates(null);
            Check(page.relates != null && page.relates.Count == 0,
                "a failed related read leaves an empty list, not a null page");
        }

        private static void WebViewParsesIntoTheWireShape()
        {
            var parsed = WebVideoViewParser.ParseWebVideoView(Ok(ViewEnvelopeJson));

            Check(parsed.IsSuccess, "web view: a code-0 envelope parses");
            Check(parsed.Value.Bvid == "BV1iv4y1M7iu", "web view: bvid is kept");
            Check(parsed.Value.Aid == "555272312", "web view: aid stays a string");
            Check(parsed.Value.Stat != null && parsed.Value.Stat.Aid == "555272312",
                "web view: stat.aid stays a string");
            Check(parsed.Value.Owner != null && parsed.Value.Owner.Mid == "2267573",
                "web view: owner.mid stays a string");
            Check(parsed.Value.Pages != null && parsed.Value.Pages.Count == 2, "web view: both parts are kept");
            Check(parsed.Value.Pages[1].Cid == "756877510" && parsed.Value.Pages[1].Page == "2",
                "web view: each part keeps cid as a string and its page number");
            Check(parsed.Value.Staff == null, "web view: a body without staff leaves staff null");
            Check(parsed.Value.OwnerExt == null, "web view: the web endpoint carries no owner_ext");
            Check(parsed.Value.UgcSeason != null && parsed.Value.UgcSeason.Title == "DIY 的 VLOG",
                "web view: ugc_season is kept");
            Check(parsed.Value.UgcSeason.Sections[0].Episodes[0].Aid == "555272312",
                "web view: a collection episode keeps its aid as a string");
        }

        private static void WebViewShapeMistakesArePayloadFailures()
        {
            CheckPayloadFailure(WebVideoViewParser.ParseWebVideoView(Ok(BadPagesEnvelopeJson)), "data.pages");
            CheckPayloadFailure(WebVideoViewParser.ParseWebVideoView(Ok(BadStaffEnvelopeJson)), "data.staff");
            CheckPayloadFailure(WebVideoViewParser.ParseWebVideoView(Ok(BadSeasonEnvelopeJson)), "data.ugc_season");
            CheckPayloadFailure(WebVideoViewParser.ParseWebVideoView(Ok(BadSectionsEnvelopeJson)),
                "data.ugc_season.sections");
        }

        private static void MapperSynthesisesShortLinkAndDefaults()
        {
            var detail = WebVideoViewMapper.MapWebVideoView(
                WebVideoViewParser.ParseWebVideoView(Ok(ViewEnvelopeJson)).Value);

            Check(detail.short_link == "https://b23.tv/BV1iv4y1M7iu", "mapper: short_link is synthesised from bvid");
            Check(detail.req_user != null, "mapper: req_user is never null");
            Check(detail.req_user.attention == 0 && detail.req_user.like == 0 && detail.req_user.coin == 0
                && detail.req_user.favorite == 0,
                "mapper: wire req_user values are not copied (it is local UI state)");
            Check(detail.owner_ext != null && detail.owner_ext.fans == 0 && !detail.owner_ext.HasFans,
                "mapper: a missing owner_ext becomes an all-default owner (fans label hides)");
            Check(detail.pages != null && detail.pages.Count == 2, "mapper: pages are carried over");
            Check(detail.aid == "555272312" && detail.stat.aid == "555272312" && detail.owner.mid == "2267573",
                "mapper: every id stays a string");
            Check(detail.stat != null && detail.stat.like == 6 && detail.stat.favorite == 3,
                "mapper: stat counters are carried over");
            Check(detail.rights != null && detail.rights.elec == 1, "mapper: rights are carried over");
            Check(detail.UgcSeason != null && detail.showUgcSeason, "mapper: ugc_season keeps the collection shown");
            Check(detail.tag == null && detail.relates == null,
                "mapper: tags and relates stay with their own reads");
        }

